def preserve_logins(apps, schema_editor):
    Member = apps.get_model("institutions", "SchoolMember")
    Login = apps.get_model("institutions", "SchoolLogin")
    Owner = apps.get_model("institutions", "OrganizationMember")
    School = apps.get_model("institutions", "School")
    alias = schema_editor.connection.alias
    for member in Member.objects.using(alias).select_related("user").all().iterator():
        Login.objects.using(alias).get_or_create(school_id=member.school_id, user_id=member.user_id,
                                               defaults={"username": member.user.username})
    for owner in Owner.objects.using(alias).filter(role="founder").select_related("user"):
        for school in School.objects.using(alias).filter(organization_id=owner.organization_id):
            Login.objects.using(alias).get_or_create(school_id=school.pk, user_id=owner.user_id,
                                                   defaults={"username": owner.user.username})


